/* From Uiverse.io by Piyush831 - Tags: form, creative, box-shadow */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: linear-gradient(to right ,grey,silver);
  padding: 40px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .login {
  font-size: 25px;
  font-weight: bold;
  text-align: center;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .flex {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .form button {
  margin-top: 25px;
  margin-bottom: 6px;
  border-radius: 10px;
  border: none;
  padding-top: 4px;
  padding-bottom: 4px;
  font-size: 19px;
  font-weight: bold;
  color: grey;
}

.__UIV_SCOPE__ .form label {
  margin-top: 20px;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .form button:hover {
  box-shadow: 2px 2px 12px white;
}

.__UIV_SCOPE__ .input {
  height: 30px;
  outline: none;
  padding: 15px;
  border-radius: 10px;
  border: none;
  font-weight: bold;
  font-size: 15px;
  box-shadow: 2px 2px 12px inset black;
}

.__UIV_SCOPE__ .span:hover {
  font-weight: bold;
}

.__UIV_SCOPE__ .color {
  color: white;
}

.__UIV_SCOPE__ .align {
  text-align: center;
}
